using ARIEC60870.Core.Model;
using ARIEC60870.Master.Model;

namespace ARIEC60870.Master.Protocol;

/// <summary>
/// Counts individually decoded, received IEC-101 spontaneous digital objects
/// after the physical session has accepted the corresponding secondary frame.
/// Counts are observations, never an assertion about the number generated by
/// an external RTU or delivered to another SCADA master.
/// </summary>
public static class Iec101SoeObservationPolicy
{
    public static bool IsAcceptedSpontaneousDigitalObject(Iec103MasterEvidenceEvent item)
        => item.ProtocolMode == Iec60870ProtocolMode.Iec101 &&
           item.Direction == FrameDirection.SlaveToMaster &&
           item.Category is "RX" or "RX Object" &&
           item.IsRelayValue &&
           item.IsRelayEdgeEvent &&
           item.TypeId is 1 or 2 or 3 or 4 or 30 or 31 &&
           item.CauseDetails is { Code: 3, Test: false, Negative: false } &&
           item.Frame?.IsChecksumValid != false &&
           item.AsduDetails is { IsHeaderValid: true, Issues.Count: 0 } &&
           item.InformationObjectDetails is { Issues.Count: 0 };
}
